1	#!/usr/bin/env node
2	// Differential harness: runs the reference executable and the Node port with the
3	// same argv and compares stdout + exit status (and, loosely, stderr).
4	//
5	// Usage:
6	//   node /workspace/difftest.mjs cases.json      # JSON array of argv arrays
7	//   node /workspace/difftest.mjs --fuzz N [seed]
8	//   node /workspace/difftest.mjs -- --a X --b Y --c z --d z   # single case
9	//
10	// Not part of the deliverable; lives outside /output on purpose.
11	
12	import { spawnSync } from 'node:child_process';
13	import { readFileSync } from 'node:fs';
14	
15	const EXE = '/workspace/dataset/test15_executable';
16	const PORT = '/output/test15.mjs';
17	
18	function runRef(argv) {
19	  const r = spawnSync(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28 });
20	  return { out: r.stdout ?? '', err: r.stderr ?? '', code: r.status };
21	}
22	
23	function runPort(argv) {
24	  const r = spawnSync(process.execPath, [PORT, ...argv], {
25	    encoding: 'utf8',
26	    maxBuffer: 1 << 28,
27	  });
28	  return { out: r.stdout ?? '', err: r.stderr ?? '', code: r.status };
29	}
30	
31	// The PyInstaller footer embeds the pid, which differs per run by design.
32	function normErr(text) {
33	  return text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
34	}
35	
36	export function compare(argv) {
37	  const a = runRef(argv);
38	  const b = runPort(argv);
39	  const problems = [];
40	  if (a.out !== b.out) problems.push('stdout');
41	  if (a.code !== b.code) problems.push('exit');
42	  if (normErr(a.err) !== normErr(b.err)) problems.push('stderr');
43	  return { argv, ref: a, port: b, problems };
44	}
45	
46	// ---- pseudo-random case generation (deterministic, seeded) -----------------
47	
48	function makeRng(seed) {
49	  let s = seed >>> 0 || 1;
50	  return () => {
51	    s ^= s << 13; s >>>= 0;
52	    s ^= s >>> 17;
53	    s ^= s << 5; s >>>= 0;
54	    return s / 4294967296;
55	  };
56	}
57	
58	const B58 = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
59	const NASTY = [
60	  '', ' ', '  ', '\t', '\n', '1', '11', '111', '1z', 'z1', '0', 'O', 'I', 'l',
61	  "'", '"', '\\', 'a\'b"c', 'é', '€', '😀', 'z ', ' z', 'z ', 'z　',
62	  '-5', '-5.5', '-x', '--a', 'a=b', 'z​', 'ü', '', 'hello world',
63	];
64	
65	function randStr(rng, alphabet, maxLen) {
66	  const n = Math.floor(rng() * (maxLen + 1));
67	  let out = '';
68	  for (let i = 0; i < n; i += 1) {
69	    out += alphabet[Math.floor(rng() * alphabet.length)];
70	  }
71	  return out;
72	}
73	
74	const ANY = ' !"#$%&\'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ'
75	  + '[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~éü€😀\t ';
76	
77	export function genCases(count, seed) {
78	  const rng = makeRng(seed);
79	  const cases = [];
80	  for (let i = 0; i < count; i += 1) {
81	    const pick = (kind) => {
82	      const roll = rng();
83	      if (roll < 0.15) return NASTY[Math.floor(rng() * NASTY.length)];
84	      if (kind === 'b58' && roll < 0.85) return randStr(rng, B58, 40);
85	      return randStr(rng, ANY, 30);
86	    };
87	    cases.push(['--a', pick('any'), '--b', pick('any'), '--c', pick('b58'), '--d', pick('b58')]);
88	  }
89	  return cases;
90	}
91	
92	// ---- entry -----------------------------------------------------------------
93	
94	const argv = process.argv.slice(2);
95	let cases;
96	if (argv[0] === '--fuzz') {
97	  cases = genCases(Number(argv[1] || 100), Number(argv[2] || 12345));
98	} else if (argv[0] === '--') {
99	  cases = [argv.slice(1)];
100	} else if (argv[0]) {
101	  cases = JSON.parse(readFileSync(argv[0], 'utf8'));
102	} else {
103	  console.error('nothing to do');
104	  process.exit(64);
105	}
106	
107	let failures = 0;
108	for (const argvCase of cases) {
109	  const result = compare(argvCase);
110	  if (result.problems.length > 0) {
111	    failures += 1;
112	    console.log('MISMATCH', result.problems.join(','), JSON.stringify(argvCase));
113	    console.log('  ref  code=%d out=%j', result.ref.code, result.ref.out);
114	    console.log('  port code=%d out=%j', result.port.code, result.port.out);
115	    if (result.problems.includes('stderr')) {
116	      console.log('  ref  err=%j', normErr(result.ref.err));
117	      console.log('  port err=%j', normErr(result.port.err));
118	    }
119	  }
120	}
121	console.log(`\n${cases.length - failures}/${cases.length} cases matched`);
122	process.exit(failures > 0 ? 1 : 0);
