23	//
24	// All four values are computed before anything is printed, so a decoding
25	// failure produces no stdout at all — just the traceback and exit status 1.
26	
27	import { ArgumentParser } from './lib/cli/argparse.mjs';
28	import { PythonError, SystemExit } from './lib/python/errors.mjs';
29	import { encodeUtf8 } from './lib/python/unicode.mjs';
30	import { printBytes } from './lib/python/print.mjs';
31	import { reportFatal } from './lib/python/traceback.mjs';
32	import { b58decode, b58encode } from './lib/base58/index.mjs';
33	
34	/** Program name used in usage/help text, as in the reference build. */
35	const PROG = 'test15_executable';
36	const SOURCE_FILE = 'test15.py';
37	const SCRIPT_NAME = 'test15';
38	
39	/**
40	 * The `<module>` frames a b58decode failure is reported against.  `colno` /
41	 * `endColno` delimit `base58.b58decode(args.X)` within the source line, which is
42	 * what the carets underline.
43	 */
44	const DECODE_FRAME = {
45	  c: { file: SOURCE_FILE, line: 13, name: '<module>', colno: 7, endColno: 31 },
46	  d: { file: SOURCE_FILE, line: 14, name: '<module>', colno: 7, endColno: 31 },
47	};
48	
49	function buildParser() {
50	  const parser = new ArgumentParser({ prog: PROG });
51	  parser.addArgument(['--a'], { required: true });
52	  parser.addArgument(['--b'], { required: true });
53	  parser.addArgument(['--c'], { required: true });
54	  parser.addArgument(['--d'], { required: true });
55	  return parser;
56	}
57	
58	/**
59	 * @param {string[]} argv arguments after the script name
60	 * @returns {number} process exit status
61	 */
62	export function main(argv) {
63	  const args = buildParser().parseArgs(argv);
64	
65	  const enc1 = b58encode(encodeUtf8(args.a)); // 编码字符串1
66	  const enc2 = b58encode(encodeUtf8(args.b)); // 编码字符串2
67	
68	  let dec1;
69	  let dec2;
70	  try {
71	    dec1 = b58decode(args.c); // 解码Base58字符串1
72	    dec2 = b58decode(args.d); // 解码Base58字符串2
73	  } catch (error) {
74	    if (!(error instanceof PythonError)) throw error;
75	    const frame = dec1 === undefined ? DECODE_FRAME.c : DECODE_FRAME.d;
76	    reportFatal(error, frame, SCRIPT_NAME, process.pid);
77	    return 1;
78	  }
79	
80	  printBytes(enc1);
81	  printBytes(enc2);
82	  printBytes(dec1);
83	  printBytes(dec2);
84	  return 0;
85	}
86	
87	try {
88	  process.exitCode = main(process.argv.slice(2));
89	} catch (error) {
90	  if (!(error instanceof SystemExit)) throw error;
91	  process.exitCode = error.code;
92	}
